# repository: только доступ к данным
def get_expenses(user_id, month):
    return Expense.query.filter_by(user_id=user_id, month=month).all()

# service: бизнес-логика, ничего не знает про HTTP и SQL
def monthly_report(user_id, month):
    expenses = get_expenses(user_id, month)
    by_category = {}
    for e in expenses:
        by_category[e.category] = by_category.get(e.category, 0) + e.amount
    return {"total": sum(e.amount for e in expenses), "by_category": by_category}

# routes: только HTTP, вызывает сервис
@bp.get("/report/<month>")
def report(month):
    return jsonify(monthly_report(current_user.id, month))

